/*=============================================================================
    IMPORTS
=============================================================================*/

import type {

    ShellKernelContract

} from "../contracts/shell-kernel-contract";

/*=============================================================================
    SHELL KERNEL
=============================================================================*/

export class ShellKernel {

    private readonly kernel: ShellKernelContract;

    constructor(
        kernel: ShellKernelContract
    ) {

        this.kernel = kernel;

    }

    /*=========================================================================
        PROVIDERS
    =========================================================================*/

    public providers() {

        return this.kernel.providers;

    }

    /*=========================================================================
        CAPABILITIES
    =========================================================================*/

    public capabilities() {

        return this.kernel.capabilities;

    }

    /*=========================================================================
        COGNITION
    =========================================================================*/

    public cognition() {

        return this.kernel.cognition;

    }

    /*=========================================================================
        WORKSPACE
    =========================================================================*/

    public workspace() {

        return this.kernel.workspace;

    }

    /*=========================================================================
        APPLICATIONS
    =========================================================================*/

    public applications() {

        return this.kernel.applications;

    }

    /*=========================================================================
        SERVICES
    =========================================================================*/

    public services() {

        return this.kernel.services;

    }

    /*=========================================================================
        MODULES
    =========================================================================*/

    public modules() {

        return this.kernel.modules;

    }

    /*=========================================================================
        ENGINES
    =========================================================================*/

    public engines() {

        return this.kernel.engines;

    }

    /*=========================================================================
        DOMAINS
    =========================================================================*/

    public domains() {

        return this.kernel.domains;

    }

    /*=========================================================================
        EVENTS
    =========================================================================*/

    public events() {

        return this.kernel.events;

    }

    /*=========================================================================
        STATE
    =========================================================================*/

    public state() {

        return this.kernel.state;

    }

    /*=========================================================================
        REGISTRY
    =========================================================================*/

    public registry() {

        return this.kernel.registry;

    }

}
